def transform(grid):
    g=[row[:] for row in grid]
    H=len(g); W=len(g[0])
    seen=[[False]*W for _ in range(H)]
    comps=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==7 and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cells=[]
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and g[nx][ny]==7 and not seen[nx][ny]:
                            seen[nx][ny]=True; st.append((nx,ny))
                comps.append(cells)
    seen2=[[False]*W for _ in range(H)]
    frames=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==2 and not seen2[i][j]:
                st=[(i,j)]; seen2[i][j]=True; cells=[]
                while st:
                    x,y=st.pop(); cells.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and g[nx][ny]==2 and not seen2[nx][ny]:
                            seen2[nx][ny]=True; st.append((nx,ny))
                frames.append(cells)
    margins=None
    for fr in frames:
        frs=[c[0] for c in fr]; fcs=[c[1] for c in fr]
        fr0,fr1=min(frs),max(frs); fc0,fc1=min(fcs),max(fcs)
        for cells in comps:
            rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
            r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
            if fr0<=r0 and r1<=fr1 and fc0<=c0 and c1<=fc1:
                margins=(r0-fr0, fr1-r1, c0-fc0, fc1-c1); break
        if margins: break
    if margins is None: margins=(2,2,2,2)
    mt,mb,ml,mr=margins
    for cells in comps:
        rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
        r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
        enclosed=False
        for fr in frames:
            frs=[c[0] for c in fr]; fcs=[c[1] for c in fr]
            if min(frs)<=r0 and r1<=max(frs) and min(fcs)<=c0 and c1<=max(fcs):
                enclosed=True; break
        if enclosed: continue
        nr0,nr1=r0-mt,r1+mb; nc0,nc1=c0-ml,c1+mr
        for j in range(nc0,nc1+1):
            if 0<=nr0<H and 0<=j<W: g[nr0][j]=2
            if 0<=nr1<H and 0<=j<W: g[nr1][j]=2
        for i in range(nr0,nr1+1):
            if 0<=i<H and 0<=nc0<W: g[i][nc0]=2
            if 0<=i<H and 0<=nc1<W: g[i][nc1]=2
    return g
